/**
 * Verify the sample-creatvise.idml fixture (generated by write-sample-creatvise.ts)
 * can be loaded, imported, and exhibits expected structure.
 */
import fs from 'node:fs';
import path from 'node:path';
import { Window } from 'happy-dom';
import JSZip from 'jszip';

const window = new Window();
(globalThis as unknown as { DOMParser: typeof DOMParser }).DOMParser =
  window.DOMParser as unknown as typeof DOMParser;
(globalThis as unknown as { document: Document }).document = window.document as unknown as Document;

import { importIdml, exportIdml } from '../src/indd/idml';
import { IDML_MIMETYPE } from '../src/indd/zip';

const FIXTURE = path.join(process.cwd(), 'artifacts', 'fixtures', 'sample-creatvise.idml');

const results: { name: string; ok: boolean; detail: string }[] = [];
const log = (name: string, ok: boolean, detail: string) => {
  results.push({ name, ok, detail });
  console.log((ok ? 'OK' : 'FAIL') + ': ' + name + ' — ' + detail);
};

async function main() {
  // 1. Fixture must exist (written by write-sample-creatvise.ts)
  const exists = fs.existsSync(FIXTURE);
  log('fixture-exists', exists, FIXTURE);
  if (!exists) {
    console.error('Run `tsx scripts/fixtures/write-sample-creatvise.ts` first.');
    process.exit(1);
  }

  // 2. Read and verify ZIP structure
  const raw = fs.readFileSync(FIXTURE);
  log('file-nonzero', raw.length > 0, `${raw.length} bytes`);

  const zip = await JSZip.loadAsync(raw);
  const mime = await zip.file('mimetype')?.async('string');
  log('mimetype', mime?.trim() === IDML_MIMETYPE, String(mime?.trim()));

  const designmap = zip.file('designmap.xml');
  log('has-designmap', designmap !== null, designmap ? 'present' : 'missing');

  const spreads = Object.keys(zip.files).filter(f => f.startsWith('Spreads/'));
  log('has-spreads', spreads.length > 0, `${spreads.length}`);

  // 3. Import
  const bytes = raw.buffer.slice(raw.byteOffset, raw.byteOffset + raw.byteLength);
  const doc = await importIdml('sample-creatvise.idml', bytes, 'idml');
  log('import-ok', !!doc, 'imported');
  log('format-indd', doc.format === 'indd', doc.format);
  log('has-roots', doc.roots.length > 0, `${doc.roots.length} roots`);
  log('has-backing', !!doc.idml, doc.idml ? 'yes' : 'no');

  // 4. Export roundtrip
  const exported = await exportIdml(doc);
  log('export-nonzero', exported.byteLength > 0, `${exported.byteLength} bytes`);

  // 5. Re-import exported
  const doc2 = await importIdml('re-imported.idml', exported, 'idml');
  log('reimport-roots', doc2.roots.length === doc.roots.length,
    `original=${doc.roots.length} reimported=${doc2.roots.length}`);

  // Summary
  const failed = results.filter(r => !r.ok);
  console.log(`\n${results.length} checks, ${results.length - failed.length} passed, ${failed.length} failed`);
  if (failed.length > 0) {
    console.error('Failures:', failed.map(f => f.name).join(', '));
    process.exit(1);
  }
}

main().catch((e) => {
  console.error('FAIL:', e);
  process.exit(1);
});
